def solve_for_N(N):
    # V[n] is true if the player who receives n wins
    # V[n] = True if (n+1 == N or 2n == N)
    # V[n] = True if (n+1 < N and V[n+1] == False)
    # V[n] = True if (2n < N and V[2n] == False)
    # Otherwise V[n] = False
    V = [False] * (N + 1)
    # V[N] is not needed but let's say the player who wrote N wins.
    # The player who receives n wins if they can write N or move to a state from which the other player loses.
    for n in range(N - 1, 0, -1):
        # Can they write N?
        if n + 1 == N or 2 * n == N:
            V[n] = True
        # Can they move to a state m where the other player loses?
        elif n + 1 < N and not V[n + 1]:
            V[n] = True
        elif 2 * n < N and not V[2 * n]:
            V[n] = True
        else:
            V[n] = False
    return V[1]

for N in range(401, 520):
    is_type_B = solve_for_N(N)
    if is_type_B:
        print(f"N={N} is type B")
        break

